response.output:
```json
{
  "item": "DP-61",
  "epics": [
    {
      "id": "DP-61-E1",
      "title": "Ingredient model gains product-identity fields",
      "stories": [
        {
          "id": "DP-61-E1-S1",
          "statement": "As a user, I want an ingredient to optionally carry brand, barcode, and package size, so a custom item can represent a specific real product rather than a generic ingredient.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {
              "id": "AC1",
              "given": "an existing ingredient record with no product-identity fields set",
              "when": "it is read or re-saved without changes",
              "then": "it remains valid; brand, barcode, packageQuantity, and packageUnit are all optional/nullable"
            },
            {
              "id": "AC2",
              "given": "a user is setting package size on an ingredient",
              "when": "only one of packageQuantity or packageUnit is provided",
              "then": "the save is rejected with a validation error requiring both to be set together"
            },
            {
              "id": "AC3",
              "given": "a user saves an ingredient with a barcode value",
              "when": "the save succeeds",
              "then": "the barcode is persisted exactly as entered and associated with that ingredient"
            }
          ]
        },
        {
          "id": "DP-61-E1-S2",
          "statement": "As a user, I want barcodes to be unique across ingredients when present, so two different products can't be confused as the same item.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {
              "id": "AC1",
              "given": "ingredient A already has barcode \"0123456789012\"",
              "when": "a user attempts to save ingredient B with the same barcode",
              "then": "the save is rejected with a validation error indicating the barcode is already in use"
            },
            {
              "id": "AC2",
              "given": "two or more ingredients have no barcode set (null)",
              "when": "they are saved",
              "then": "no uniqueness conflict occurs between them"
            },
            {
              "id": "AC3",
              "given": "an ingredient currently holds a barcode",
              "when": "a user clears the barcode field and saves",
              "then": "the save succeeds and that barcode value becomes available for reuse by another ingredient"
            }
          ]
        }
      ]
    },
    {
      "id": "DP-61-E2",
      "title": "Zero-quantity pantry rows are valid and visible as out of stock",
      "stories": [
        {
          "id": "DP-61-E2-S1",
          "statement": "As a user, I want a pantry row to stay at zero quantity instead of being deleted, so running out of a product doesn't erase it from my pantry.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {
              "id": "AC1",
              "given": "an existing pantry row for an ingredient with quantity > 0",
              "when": "its quantity is updated to 0",
              "then": "the save succeeds and the row is not deleted"
            },
            {
              "id": "AC2",
              "given": "the previous schema constraint requiring quantity > 0",
              "when": "a pantry row is saved with quantity = 0",
              "then": "the save is accepted; the constraint no longer blocks zero values"
            },
            {
              "id": "AC3",
              "given": "a pantry row whose quantity has dropped to 0",
              "when": "the row is inspected afterward",
              "then": "the linked ingredient's identity fields (name, brand, barcode, package size) are unchanged"
            }
          ]
        },
        {
          "id": "DP-61-E2-S2",
          "statement": "As a user, I want zero-quantity items to show clearly as out of stock, so I can tell at a glance what I need to restock.",
          "domains": ["ux"],
          "acceptance_criteria": [
            {
              "id": "AC1",
              "given": "a pantry row with quantity 0",
              "when": "viewing the /pantry list",
              "then": "the row is displayed with an \"out of stock\" indicator rather than being hidden or omitted"
            },
            {
              "id": "AC2",
              "given": "a pantry row with quantity 0",
              "when": "viewing /pantry/[id]",
              "then": "the detail page shows the out-of-stock state alongside the retained product identity"
            },
            {
              "id": "AC3",
              "given": "a pantry row with quantity > 0",
              "when": "viewing /pantry list or /pantry/[id]",
              "then": "no out-of-stock indicator is shown"
            }
          ]
        }
      ]
    },
    {
      "id": "DP-61-E3",
      "title": "One-step custom item creation from the pantry page",
      "stories": [
        {
          "id": "DP-61-E3-S1",
          "statement": "As a user, I want a \"Create custom item\" button on /pantry, so I don't have to leave the page to add a branded product I don't yet have in the catalog.",
          "domains": ["ux"],
          "acceptance_criteria": [
            {
              "id": "AC1",
              "given": "a user is on /pantry",
              "when": "the page renders",
              "then": "a \"Create custom item\" button is visible"
            },
            {
              "id": "AC2",
              "given": "the user clicks \"Create custom item\"",
              "when": "the action is triggered",
              "then": "a form opens on /pantry itself, without navigating to /ingredients/new"
            },
            {
              "id": "AC3",
              "given": "the create-item form is open",
              "when": "the user cancels it",
              "then": "no ingredient or pantry row is created and the form closes"
            }
          ]
        },
        {
          "id": "DP-61-E3-S2",
          "statement": "As a user, I want creating a custom item to produce both the ingredient and its pantry row in one action, so the two-step workflow collapses into one.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {
              "id": "AC1",
              "given": "a user submits the create-item form with a name and quantity",
              "when": "the form is submitted",
              "then": "a single Server Action creates both the custom ingredient and its pantry row together"
            },
            {
              "id": "AC2",
              "given": "the user also supplies brand, barcode, packageQuantity, and/or packageUnit",
              "when": "the form is submitted",
              "then": "those values are persisted on the newly created ingredient"
            },
            {
              "id": "AC3",
              "given": "the submission fails validation (e.g. duplicate barcode)",
              "when": "the Server Action errors",
              "then": "neither the ingredient nor the pantry row is created, and the error is surfaced to the user"
            },
            {
              "id": "AC4",
              "given": "a user submits the form with quantity set to 0",
              "when": "the Server Action runs",
              "then": "the created pantry row is accepted at zero quantity and shows as out of stock"
            }
          ]
        }
      ]
    },
    {
      "id": "DP-61-E4",
      "title": "Surface product identity in the ingredient form and pantry detail view",
      "stories": [
        {
          "id": "DP-61-E4-S1",
          "statement": "As a user, I want the ingredient form to capture brand, barcode, and package size, so product identity can be entered consistently whether I come from /ingredients/new or /pantry.",
          "domains": ["ux"],
          "acceptance_criteria": [
            {
              "id": "AC1",
              "given": "a user opens /ingredients/new or edits an existing ingredient",
              "when": "the form renders",
              "then": "optional fields for brand, barcode, packageQuantity, and packageUnit are present"
            },
            {
              "id": "AC2",
