              "id": "ac-1",
              "given": "a dead-lettered message exists on a subscription",
              "when": "the operator requests its detail by subscription id and message id",
              "then": "the response includes the full message payload, the delivery attempt count, the most recent failure reason, and the timestamp it was dead-lettered"
            },
            {
              "id": "ac-2",
              "given": "the message id supplied does not exist in that subscription's dead-letter queue",
              "when": "the operator requests its detail",
              "then": "the system returns a not-found error and does not expose any message data from other subscriptions"
            },
            {
              "id": "ac-3",
              "given": "a message id that was previously dead-lettered on the subscription but is no longer in the dead-lettered state (for example, it was already redriven)",
              "when": "the operator requests its detail",
              "then": "the system indicates the message is no longer dead-lettered rather than returning stale dead-letter detail, so the operator does not act on outdated information"
            },
            {
              "id": "ac-4",
              "given": "a dead-lettered message that has failed more than one delivery attempt",
              "when": "the operator requests its detail",
              "then": "the response surfaces the failure reason for each recorded attempt, or an equivalent summary, so the operator can distinguish a transient failure from a persistent one"
            }
          ]
        }
      ]
    },
    {
      "id": "epic-dlq-recovery",
      "title": "Redrive Dead-Lettered Messages",
