            },
            {
              "id": "ac-5",
              "given": "a redrive request references a message id that belongs to a different subscription than the one specified",
              "when": "the operator submits that request",
              "then": "the system rejects that id as not-found for the given subscription and does not redrive it"
            }
          ]
        },
