          "acceptance_criteria": [
            {
              "id": "ac-1",
              "given": "a subscription has one or more dead-lettered messages",
              "when": "the operator submits a bulk redrive request for that subscription",
              "then": "every message in the dead-letter queue at the time of the request is re-enqueued for delivery and removed from the dead-letter queue, and the response reports a summary count of messages redriven"
            },
            {
              "id": "ac-2",
              "given": "a subscription currently has zero dead-lettered messages",
              "when": "the operator submits a bulk redrive request for it",
              "then": "the request completes successfully reporting zero messages redriven, and this is not treated as an error"
            },
            {
              "id": "ac-3",
              "given": "a bulk redrive for a subscription has already completed",
              "when": "the operator submits the identical bulk redrive request again",
              "then": "messages already redriven by the prior call are not re-enqueued a second time; only messages still present in the dead-letter queue, if any, are processed"
            },
            {
              "id": "ac-4",
              "given": "messages on the subscription are actively in-flight for delivery at the time of the bulk redrive",
              "when": "the bulk redrive executes",
              "then": "those in-flight messages are left undisturbed - their delivery attempt is not restarted, duplicated, or cancelled by the redrive"
            },
            {
              "id": "ac-5",
              "given": "a subscription has a large number of dead-lettered messages spanning multiple pages",
              "when": "the operator submits a bulk redrive request",
              "then": "the system processes all of them internally and returns a single summary result, without requiring the operator to page through and submit multiple requests"
            }
